// Стандарт С++20:

#include <iostream>
#include <format>
#include <cstdint>
#include <memory>

int main()
{
    int32_t nights{1001};                                                   // Инициализация переменной типа int;
    const auto pt = std::make_unique<int32_t>(1001);                        // std::make_unique<int32_t> - выделение в памяти (куче) через new для значения типа int32_t и выдает умный указаетель. Квалификатор const защащает указаетль от случайного изменения. Тип auto дает понять компилятору, что нужно записать тип std::unique_ptr<int32_t>;
    std::cout << std::format("Значение nights = {} расположено {}\n",
                              nights, static_cast<const void*>(&nights)); // Объект cout при помощи оператора << выводит отформатированную строку со значением переменной и адресом, где расположена переменная;
    std::cout << std::format("Значение int {} расположено {}\n",         // Объект cout при помощи оператора << выводит отформатированную строку со значением расположенного в выделенной памяти, на который ссылается указатель и адресом значения на который указывает pt.
                         *pt, static_cast<const void*>(pt.get()));      // pt.get() - функция get() достает простой указаетль типа int32_t из умного указателя pt, static_cast<const void*> приводит в простой универсальный указатель, который содержит адрес;
    const auto pd = std::make_unique<double>(1000000.1);                    // std::make_unique<double> - выделение в памяти (куче) через new для значения типа double и выдает умный указатель. Квалификатор const защищает указаетль от случайного изменения. Тип auto дает пончть компилятору, что нужно записать тип std::unique_ptr<double>;
    std::cout << std::format("Значение double {} расположено {}\n",      // Объект cout при помощи оператора << выводит отформатированную строку со значением расположенного в выделенной памяти, на который ссылается указатель и адресом значения на который указывает pd.
                             *pd, static_cast<const void*>(pd.get()));  // pd.get() - функцтя get() достает простой указатель типа double из умного указаетеля pd, static_cast<const void*> приводит в простой универсальный указатель, который содержит адрес;
    std::cout << std::format("Расположение указателя pd {}\n",           // Объект cout при помощи оператора << выводит отформатированную строку строку с адресом расположения указаетля;
                                 static_cast<const void*>(&pd));
    std::cout << std::format("Размер указателя pt = {}, размер значения указателя pt = {}\n",
                                    sizeof(pt), sizeof(*pt));               // Объект cout при помощи оператора << выводит отформатированную строку с размером указателя pt и размером типа значения, на который указывает указатель;
    std::cout << std::format("Размер указателя pd = {}, размер значения указателя pd = {}\n",
                                    sizeof(pd), sizeof(*pd));               // Объект cout при помощи оператора << выводит отформатированную строку с размером указателя pd и размером типа значения, на который указывает указатель;
}


/*
   Выделенная память под динамаческие данные, на которые указывает указатель,  освобождается по завершению функции,
   автоматически вызывая встроенный деструктор в умный указатель.
*/


